<?php use Addons\Grh\GrhService as S; require __DIR__ . '/_h.php'; ?>
<?php if ($actifs): ?><div class="card mb-3"><div class="card-header"><i class="bi bi-wallet2"></i> <?= e(t('Accorder une avance sur salaire')) ?></div><div class="card-body"><form method="post" action="<?= e(url('/grh/avances')) ?>" class="row g-2"><?= csrf_field() ?>
  <?= grh_select('employe_id', 'Employé', grh_opts($actifs, fn ($r) => $r['last_name'] . ' ' . $r['first_name'] . ' (' . $r['matricule'] . ')', 'Choisir…'), '', 'required', 'col-md-3', false) ?><?= grh_field('amount', 'Montant de l\'avance', '', 'text', 'required inputmode="decimal"', 'col-md-2') ?><?= grh_field('monthly', 'Retenue mensuelle', '', 'text', 'inputmode="decimal" placeholder="' . e(t('tout en une fois')) . '"', 'col-md-2') ?>
  <?= grh_field('granted_on', 'Date', date('Y-m-d'), 'date', 'required', 'col-md-2') ?><?= grh_field('reason', 'Motif', '', 'text', 'maxlength="250"', 'col-md-2') ?><div class="col-md-1 d-flex align-items-end"><button class="btn btn-sm btn-primary w-100"><?= e(t('Accorder')) ?></button></div></form>
  <p class="small text-secondary mb-0 mt-2"><?= e(t('Les retenues mensuelles d\'un employé ne dépassent jamais le tiers de son salaire. La retenue se fait à la validation de la paie.')) ?></p></div></div><?php endif; ?>
<div class="card"><div class="table-responsive"><table class="table table-sm align-middle mb-0 small"><thead><tr><th><?= e(t('Employé')) ?></th><th><?= e(t('Date')) ?></th><th><?= e(t('Motif')) ?></th><th class="num"><?= e(t('Avance')) ?></th><th class="num"><?= e(t('Retenue / mois')) ?></th><th class="num"><?= e(t('Reste dû')) ?></th><th><?= e(t('État')) ?></th><th></th></tr></thead><tbody>
<?php foreach ($rows as $a): ?><tr><td><a href="<?= e(url('/grh/employes/' . $a['employe_id'])) ?>"><?= e($a['last_name'] . ' ' . $a['first_name']) ?></a></td><td><?= e(fdate($a['granted_on'], false)) ?></td><td><?= e($a['reason']) ?></td><td class="num"><?= money($a['amount']) ?></td><td class="num"><?= money($a['monthly']) ?></td><td class="num fw-semibold"><?= money($a['remaining']) ?></td>
  <td><?= grh_badge(S::AVANCE_STATUS[$a['status']], ['en_cours' => 'warning', 'soldee' => 'success', 'annulee' => 'secondary'][$a['status']]) ?></td>
  <td class="text-end"><?php if ($a['status'] === 'en_cours' && (float) $a['remaining'] >= (float) $a['amount']): ?><form method="post" action="<?= e(url('/grh/avances/' . $a['id'] . '/annuler')) ?>" data-confirm="<?= e(t('Annuler cette avance ?')) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger"><i class="bi bi-x-lg"></i></button></form><?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="8" class="text-center text-secondary py-4"><?= e(t('Aucune avance.')) ?></td></tr><?php endif; ?></tbody></table></div></div>
